// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(amount <= address(c).balance || caller == c.owner());
        vm.deal(address(c), amount);
        address target = address(new Reverter());
        vm.prank(caller);
        bool ok = true;
        try c.sendMoney(target, amount) { ok = true; } catch { ok = false; }
        if (caller == c.owner()) {
            assertTrue(ok);
        } else {
            assertTrue(!ok);
        }
    }
}
contract Reverter { fallback() external payable { revert(); } }
